import{_ as e,o as t,c as o,a2 as s}from"./chunks/framework.C0KMm31j.js";const i="/Nav2ArticlesSite/article-assets/2026-07-27/rotation_shim_core_01_overview.png",n="/Nav2ArticlesSite/article-assets/2026-07-27/rotation_shim_core_02_state_delegate.png",l="/Nav2ArticlesSite/article-assets/2026-07-27/rotation_shim_core_03_path_sampling.png",r="/Nav2ArticlesSite/article-assets/2026-07-27/rotation_shim_core_04_hysteresis.png",d="/Nav2ArticlesSite/article-assets/2026-07-27/rotation_shim_core_05_angular_command.png",p="/Nav2ArticlesSite/article-assets/2026-07-27/rotation_shim_core_06_collision.png",P=JSON.parse('{"title":"先别急着走：Nav2 Rotation Shim 如何在路径跟踪前把方向“扶正”？","description":"一条新路径已经规划出来，机器人却正横着面对它。此时直接把控制权交给 DWB、RPP 或 MPPI，主控制器既要纠正巨大航向误差，又要开始平移，起始轨迹很容易拐出大弧、贴近障碍，甚至根本找不到有效速度。","frontmatter":{"title":"先别急着走：Nav2 Rotation Shim 如何在路径跟踪前把方向“扶正”？","description":"一条新路径已经规划出来，机器人却正横着面对它。此时直接把控制权交给 DWB、RPP 或 MPPI，主控制器既要纠正巨大航向误差，又要开始平移，起始轨迹很容易拐出大弧、贴近障碍，甚至根本找不到有效速度。","date":"2026-07-27","section":"三 · 局部控制与速度生成","readingTime":15,"source":"2026-07-27/nav2_rotation_shim_controller_core_algorithm.md","status":"published","cover":"/article-assets/2026-07-27/rotation_shim_core_01_overview.png","head":[["link",{"rel":"canonical","href":"https://zpy560.github.io/Nav2ArticlesSite/nav2/nav2-rotation-shim-controller-core-algorithm"}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:title","content":"先别急着走：Nav2 Rotation Shim 如何在路径跟踪前把方向“扶正”？"}],["meta",{"property":"og:description","content":"一条新路径已经规划出来，机器人却正横着面对它。此时直接把控制权交给 DWB、RPP 或 MPPI，主控制器既要纠正巨大航向误差，又要开始平移，起始轨迹很容易拐出大弧、贴近障碍，甚至根本找不到有效速度。"}],["meta",{"property":"og:url","content":"https://zpy560.github.io/Nav2ArticlesSite/nav2/nav2-rotation-shim-controller-core-algorithm"}],["meta",{"property":"og:image","content":"https://zpy560.github.io/Nav2ArticlesSite/article-assets/2026-07-27/rotation_shim_core_01_overview.png"}],["meta",{"property":"article:published_time","content":"2026-07-27"}],["meta",{"name":"twitter:title","content":"先别急着走：Nav2 Rotation Shim 如何在路径跟踪前把方向“扶正”？"}],["meta",{"name":"twitter:description","content":"一条新路径已经规划出来，机器人却正横着面对它。此时直接把控制权交给 DWB、RPP 或 MPPI，主控制器既要纠正巨大航向误差，又要开始平移，起始轨迹很容易拐出大弧、贴近障碍，甚至根本找不到有效速度。"}],["meta",{"name":"twitter:image","content":"https://zpy560.github.io/Nav2ArticlesSite/article-assets/2026-07-27/rotation_shim_core_01_overview.png"}]],"prev":{"text":"只追一根“胡萝卜”，为何还能过急弯、贴窄道？拆解 Nav2 RPP 核心算法","link":"/nav2/nav2-regulated-pure-pursuit-controller-core-algorithm"},"next":{"text":"机器人明明在动，却被 Nav2 判定“卡住”？拆解 5 个进展与到点检查器","link":"/nav2/nav2-controller-checkers-source-walkthrough"}},"headers":[],"relativePath":"nav2/nav2-rotation-shim-controller-core-algorithm.md","filePath":"nav2/nav2-rotation-shim-controller-core-algorithm.md","lastUpdated":null}'),c={name:"nav2/nav2-rotation-shim-controller-core-algorithm.md"};function h(_,a,m,u,g,b){return t(),o("div",null,[...a[0]||(a[0]=[s('<h1 id="先别急着走-nav2-rotation-shim-如何在路径跟踪前把方向-扶正" tabindex="-1">先别急着走：Nav2 Rotation Shim 如何在路径跟踪前把方向“扶正”？ <a class="header-anchor" href="#先别急着走-nav2-rotation-shim-如何在路径跟踪前把方向-扶正" aria-label="Permalink to &quot;先别急着走：Nav2 Rotation Shim 如何在路径跟踪前把方向“扶正”？&quot;">​</a></h1><p>一条新路径已经规划出来，机器人却正横着面对它。此时直接把控制权交给 DWB、RPP 或 MPPI，主控制器既要纠正巨大航向误差，又要开始平移，起始轨迹很容易拐出大弧、贴近障碍，甚至根本找不到有效速度。</p><p>Nav2 Rotation Shim Controller 的思路很直接：它不再发明一套路径跟踪算法，而是在主控制器前面加一道“方向门”。新路径到来时，先观察路径前方的粗略走向；方向差太大就原地旋转，方向进入安全窗口后立即退出，把同一条 Path 交还给真正的主控制器。</p><p>本文基于当前本地 <code>navigation2</code>、<code>nav2_rotation_shim_controller 1.1.20</code> 源码、单元测试和现用参数，只拆路径初始航向采样、旋转接管与退出、角速度生成、原地碰撞预测、目标末端旋转，以及向嵌套主控制器委托的核心算法。</p><p><img src="'+i+'" alt="Rotation Shim 核心算法总览"></p><h2 id="一、它是控制器前面的接管层" tabindex="-1">一、它是控制器前面的接管层 <a class="header-anchor" href="#一、它是控制器前面的接管层" aria-label="Permalink to &quot;一、它是控制器前面的接管层&quot;">​</a></h2><h3 id="_1-1-输入与普通-controller-完全相同" tabindex="-1">1.1 输入与普通 Controller 完全相同 <a class="header-anchor" href="#_1-1-输入与普通-controller-完全相同" aria-label="Permalink to &quot;1.1 输入与普通 Controller 完全相同&quot;">​</a></h3><p><code>RotationShimController</code> 实现 <code>nav2_core::Controller</code>。Controller Server 每个控制周期仍然传入：</p><ul><li>当前机器人 <code>PoseStamped</code>。</li><li>当前机器人 <code>Twist</code>。</li><li>当前任务使用的 <code>GoalChecker</code>。</li><li>之前通过 <code>setPlan()</code> 保存的全局 <code>Path</code>。</li><li>TF、Local Costmap 和机器人 Footprint。</li></ul><p>输出仍是一个 <code>TwistStamped</code>。Rotation Shim 接管时只填写 <code>angular.z</code>，线速度保持零；不需要接管时，输出就是内部主控制器的结果。</p><h3 id="_1-2-它不负责正常路径跟踪" tabindex="-1">1.2 它不负责正常路径跟踪 <a class="header-anchor" href="#_1-2-它不负责正常路径跟踪" aria-label="Permalink to &quot;1.2 它不负责正常路径跟踪&quot;">​</a></h3><p>配置项 <code>primary_controller</code> 指定真正的跟踪器。当前三套主要配置都把它设为：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>primary_controller = dwb_core::DWBLocalPlanner</span></span></code></pre></div><p>Rotation Shim 只解决“新路径起步方向差太大”这一个局部问题。通过退出阈值后，曲率跟踪、轨迹采样、避障打分、速度调节和终点收敛全部由 DWB 继续完成。</p><h3 id="_1-3-同一个插件标识承载两层参数" tabindex="-1">1.3 同一个插件标识承载两层参数 <a class="header-anchor" href="#_1-3-同一个插件标识承载两层参数" aria-label="Permalink to &quot;1.3 同一个插件标识承载两层参数&quot;">​</a></h3><p>内部主控制器使用与 Rotation Shim 相同的插件名完成 <code>configure()</code>。因此当前 YAML 的 <code>RotationShimController</code> 配置组前半部分是 Shim 参数，后半部分直接放置 DWB 参数。</p><p>这不是把两套算法混成一套，而是一个插件命名空间中嵌套了两个 Controller 对象。</p><h3 id="_1-4-当前已加载但不是默认控制器" tabindex="-1">1.4 当前已加载但不是默认控制器 <a class="header-anchor" href="#_1-4-当前已加载但不是默认控制器" aria-label="Permalink to &quot;1.4 当前已加载但不是默认控制器&quot;">​</a></h3><p>当前 <code>nav2_regulated_modules</code>、<code>myagv_test_bringup</code> 和 <code>mytb3_bringup</code> 都会加载 Rotation Shim，但默认控制器分别是 DWB、DWB 和 GracefulController。</p><p>因此本文解释的是当前可切换使用的算法与参数，不代表现有启动链默认会经过这层 Shim。</p><h2 id="二、新-path-会重新打开方向门" tabindex="-1">二、新 Path 会重新打开方向门 <a class="header-anchor" href="#二、新-path-会重新打开方向门" aria-label="Permalink to &quot;二、新 Path 会重新打开方向门&quot;">​</a></h2><p><img src="'+n+`" alt="新路径、Shim 状态与主控制器委托"></p><h3 id="_2-1-setplan-同时喂给两层控制器" tabindex="-1">2.1 setPlan 同时喂给两层控制器 <a class="header-anchor" href="#_2-1-setplan-同时喂给两层控制器" aria-label="Permalink to &quot;2.1 setPlan 同时喂给两层控制器&quot;">​</a></h3><p>收到新 Path 时，<code>setPlan()</code> 完成四件事：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>path_updated_ = true</span></span>
<span class="line"><span>current_path_ = path</span></span>
<span class="line"><span>primary_controller_-&gt;setPlan(path)</span></span>
<span class="line"><span>position_goal_checker_-&gt;reset()</span></span></code></pre></div><p><code>current_path_</code> 供 Shim 计算路径初始方向，原始 Path 同时交给 DWB。等方向对齐后，无需再次复制或转换路径，主控制器可以立即开始工作。</p><h3 id="_2-2-path-updated-是一次路径级触发器" tabindex="-1">2.2 path_updated_ 是一次路径级触发器 <a class="header-anchor" href="#_2-2-path-updated-是一次路径级触发器" aria-label="Permalink to &quot;2.2 path_updated_ 是一次路径级触发器&quot;">​</a></h3><p>只有 <code>path_updated_=true</code> 时，起步旋转逻辑才会运行。方向已经进入退出窗口后，源码把它置为 <code>false</code>，之后每个周期都直接委托主控制器。</p><p>这意味着 Shim 不会在整条路径跟踪期间持续检查局部路径切线。它处理的是“新 Path 的开场”，不是每一个急弯。</p><h3 id="_2-3-每次重规划都可能重新接管" tabindex="-1">2.3 每次重规划都可能重新接管 <a class="header-anchor" href="#_2-3-每次重规划都可能重新接管" aria-label="Permalink to &quot;2.3 每次重规划都可能重新接管&quot;">​</a></h3><p>上游再次调用 <code>setPlan()</code> 时，即使机器人正在正常跟踪，<code>path_updated_</code> 也会重新置为 <code>true</code>。下一周期会重新采样新 Path 的前向点，并决定是否再次原地旋转。</p><p>所以它对全局重规划、控制器恢复后重新下发路径、目标更新都敏感。</p><h3 id="_2-4-采样或-tf-失败会放弃-shim" tabindex="-1">2.4 采样或 TF 失败会放弃 Shim <a class="header-anchor" href="#_2-4-采样或-tf-失败会放弃-shim" aria-label="Permalink to &quot;2.4 采样或 TF 失败会放弃 Shim&quot;">​</a></h3><p>找不到有效采样点、TF 变换失败，或者旋转碰撞预测抛出异常时，起步分支捕获异常并清除 <code>path_updated_</code>，然后继续调用主控制器。</p><p>这里的语义不是“Shim 失败则整周期停止”，而是“无法安全完成前置修正时，把决定权交还主控制器”。如果主控制器也失败，异常才继续向 Controller Server 传播。</p><h2 id="三、路径航向来自前方一个采样点" tabindex="-1">三、路径航向来自前方一个采样点 <a class="header-anchor" href="#三、路径航向来自前方一个采样点" aria-label="Permalink to &quot;三、路径航向来自前方一个采样点&quot;">​</a></h2><p><img src="`+l+`" alt="前方采样点与航向误差"></p><h3 id="_3-1-搜索从-path-首-pose-开始" tabindex="-1">3.1 搜索从 Path 首 Pose 开始 <a class="header-anchor" href="#_3-1-搜索从-path-首-pose-开始" aria-label="Permalink to &quot;3.1 搜索从 Path 首 Pose 开始&quot;">​</a></h3><p><code>getSampledPathPt()</code> 要求 Path 至少包含两个 Pose。它把首 Pose 记作起点，然后向后寻找首个满足：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>hypot(</span></span>
<span class="line"><span>  pose_i.x - pose_0.x,</span></span>
<span class="line"><span>  pose_i.y - pose_0.y</span></span>
<span class="line"><span>) &gt;= forward_sampling_distance</span></span></code></pre></div><p>的 Path Pose。</p><p>当前 <code>forward_sampling_distance=0.5 m</code>。因此算法不会直接使用紧邻首点的离散 Pose，而是尽量避开路径首端的密集点、量化噪声和极短折线。</p><h3 id="_3-2-这里测量的是弦长" tabindex="-1">3.2 这里测量的是弦长 <a class="header-anchor" href="#_3-2-这里测量的是弦长" aria-label="Permalink to &quot;3.2 这里测量的是弦长&quot;">​</a></h3><p>搜索条件使用采样点到 Path 首点的欧氏距离，不是沿 Path 累计的弧长。</p><p>如果起始路径先绕出弯再回到首点附近，累计长度可能已经超过 <code>0.5 m</code>，但欧氏距离仍不足，Shim 会继续向后找。它得到的是“半米尺度上的净前进方向”，不是严格的路径切线。</p><h3 id="_3-3-采样点被变换到-base-frame" tabindex="-1">3.3 采样点被变换到 base frame <a class="header-anchor" href="#_3-3-采样点被变换到-base-frame" aria-label="Permalink to &quot;3.3 采样点被变换到 base frame&quot;">​</a></h3><p>找到的 Pose 使用 Path 的 frame 和当前时间戳，经 <code>nav2_util::transformPoseInTargetFrame()</code> 变换到机器人 base frame。</p><p>在 base frame 中机器人位于原点并朝向 <code>+x</code>。采样点坐标为 <code>(x_s,y_s)</code> 时，待对齐角度就是：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>e_theta = atan2(y_s, x_s)</span></span></code></pre></div><p><code>e_theta&gt;0</code> 表示路径粗略方向在机器人左侧，<code>e_theta&lt;0</code> 表示在右侧。</p><h3 id="_3-4-采样不到不强制旋转" tabindex="-1">3.4 采样不到不强制旋转 <a class="header-anchor" href="#_3-4-采样不到不强制旋转" aria-label="Permalink to &quot;3.4 采样不到不强制旋转&quot;">​</a></h3><p>如果整条 Path 都没有点达到 <code>forward_sampling_distance</code>，函数抛出异常。外层随后关闭本次路径的 Shim 检查并委托主控制器。</p><p>短路径因此不会因为缺少半米采样点而永久卡在前置逻辑中。代价是主控制器必须自己处理短路径的大航向误差。</p><h2 id="四、双阈值迟滞阻止控制权抖动" tabindex="-1">四、双阈值迟滞阻止控制权抖动 <a class="header-anchor" href="#四、双阈值迟滞阻止控制权抖动" aria-label="Permalink to &quot;四、双阈值迟滞阻止控制权抖动&quot;">​</a></h2><p><img src="`+r+'" alt="双阈值迟滞状态机"></p><h3 id="_4-1-进入旋转使用大阈值" tabindex="-1">4.1 进入旋转使用大阈值 <a class="header-anchor" href="#_4-1-进入旋转使用大阈值" aria-label="Permalink to &quot;4.1 进入旋转使用大阈值&quot;">​</a></h3><p>尚未进入旋转状态时，比较条件为：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>abs(e_theta) &gt; angular_dist_threshold</span></span></code></pre></div><p>当前 <code>angular_dist_threshold=0.785 rad</code>，约为四十五度。误差没有超过该值时，Shim 不接管，直接把 Path 交给 DWB。</p><h3 id="_4-2-已旋转时使用更小的退出阈值" tabindex="-1">4.2 已旋转时使用更小的退出阈值 <a class="header-anchor" href="#_4-2-已旋转时使用更小的退出阈值" aria-label="Permalink to &quot;4.2 已旋转时使用更小的退出阈值&quot;">​</a></h3><p>一旦 <code>in_rotation_=true</code>，下一周期改用：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>abs(e_theta) &gt; angular_disengage_threshold</span></span></code></pre></div><p>当前 <code>angular_disengage_threshold=0.3925 rad</code>，约为二十二点五度。误差降到该范围内，源码才会清除 <code>path_updated_</code>，结束前置旋转。</p><h3 id="_4-3-中间区间形成迟滞带" tabindex="-1">4.3 中间区间形成迟滞带 <a class="header-anchor" href="#_4-3-中间区间形成迟滞带" aria-label="Permalink to &quot;4.3 中间区间形成迟滞带&quot;">​</a></h3><p>误差位于 <code>0.3925～0.785 rad</code> 时，行为取决于历史状态：</p><ul><li>从未接管过：继续由 DWB 跟踪。</li><li>已经在旋转：继续旋转，直到误差小于退出阈值。</li></ul><p>这段迟滞带防止 TF 噪声、里程计抖动或离散 Path 点变化让控制权在 Shim 与 DWB 之间反复切换。</p><h3 id="_4-4-比较条件都是严格大于" tabindex="-1">4.4 比较条件都是严格大于 <a class="header-anchor" href="#_4-4-比较条件都是严格大于" aria-label="Permalink to &quot;4.4 比较条件都是严格大于&quot;">​</a></h3><p>误差恰好等于进入阈值时不会接管，恰好等于退出阈值时也会退出旋转。</p><p>这是实现上的边界值语义。调参时不应把阈值当成带滞回容差的近似比较。</p><h2 id="五、角速度是目标值与单周期可达窗口的交集" tabindex="-1">五、角速度是目标值与单周期可达窗口的交集 <a class="header-anchor" href="#五、角速度是目标值与单周期可达窗口的交集" aria-label="Permalink to &quot;五、角速度是目标值与单周期可达窗口的交集&quot;">​</a></h2><p><img src="'+d+`" alt="闭环与开环角速度生成"></p><h3 id="_5-1-航向误差只决定旋转方向" tabindex="-1">5.1 航向误差只决定旋转方向 <a class="header-anchor" href="#_5-1-航向误差只决定旋转方向" aria-label="Permalink to &quot;5.1 航向误差只决定旋转方向&quot;">​</a></h3><p>目标角速度幅值固定为 <code>rotate_to_heading_angular_vel</code>：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>w_target =</span></span>
<span class="line"><span>  sign(e_theta) * rotate_to_heading_angular_vel</span></span></code></pre></div><p>当前目标幅值为 <code>0.8 rad/s</code>。误差九十度和误差一百七十度会得到相同的目标角速度，只是需要持续不同时间。</p><h3 id="_5-2-闭环模式读取实测角速度" tabindex="-1">5.2 闭环模式读取实测角速度 <a class="header-anchor" href="#_5-2-闭环模式读取实测角速度" aria-label="Permalink to &quot;5.2 闭环模式读取实测角速度&quot;">​</a></h3><p><code>closed_loop=true</code> 时，当前角速度取本周期输入的：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>velocity.angular.z</span></span></code></pre></div><p>也就是 Controller Server 提供的 Odom 速度反馈。Shim 的加速度窗口围绕实际旋转速度展开，能够补偿执行器未完全跟随上一条命令的情况。</p><h3 id="_5-3-开环模式读取上一条命令" tabindex="-1">5.3 开环模式读取上一条命令 <a class="header-anchor" href="#_5-3-开环模式读取上一条命令" aria-label="Permalink to &quot;5.3 开环模式读取上一条命令&quot;">​</a></h3><p><code>closed_loop=false</code> 时，当前角速度取 <code>last_angular_vel_</code>。激活时该变量先放入一个最大浮点数哨兵，首条命令再把它解释为零。</p><p>之后每周期都以上一条输出作为当前状态。单元测试在 Odom 故意给出错误角速度时，开环输出仍按 <code>-0.16</code>、<code>-0.32 rad/s</code> 连续递增，证明反馈值没有进入开环窗口。</p><h3 id="_5-4-加速度限制由控制频率离散化" tabindex="-1">5.4 加速度限制由控制频率离散化 <a class="header-anchor" href="#_5-4-加速度限制由控制频率离散化" aria-label="Permalink to &quot;5.4 加速度限制由控制频率离散化&quot;">​</a></h3><p>源码计算：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>dt = 1 / controller_frequency</span></span>
<span class="line"><span>w_min = w_current - max_angular_accel * dt</span></span>
<span class="line"><span>w_max = w_current + max_angular_accel * dt</span></span>
<span class="line"><span>w_cmd = clamp(w_target, w_min, w_max)</span></span></code></pre></div><p>当前 Controller Server 为 <code>20 Hz</code>，<code>dt=0.05 s</code>，<code>max_angular_accel=3.2 rad/s²</code>，所以每周期角速度最多变化：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>delta_w_max = 3.2 * 0.05 = 0.16 rad/s</span></span></code></pre></div><p>从静止开始时，命令会按 <code>0.16</code>、<code>0.32</code>、<code>0.48</code>、<code>0.64</code>、<code>0.8 rad/s</code> 逐步爬升。</p><h3 id="_5-5-源码没有按剩余角度提前刹停" tabindex="-1">5.5 源码没有按剩余角度提前刹停 <a class="header-anchor" href="#_5-5-源码没有按剩余角度提前刹停" aria-label="Permalink to &quot;5.5 源码没有按剩余角度提前刹停&quot;">​</a></h3><p>这里与 RPP 的原地旋转算法不同。Rotation Shim 只有目标角速度和加速度窗口，没有：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>sqrt(2 * max_angular_accel * abs(e_theta))</span></span></code></pre></div><p>这样的制动距离上界。</p><p>接近退出阈值时，命令仍可能保持较高角速度，直到下一周期误差进入退出窗口，再突然把控制权交给 DWB。实际制动依赖底盘、下游 Velocity Smoother 和主控制器接手后的命令变化。</p><h3 id="_5-6-setspeedlimit-不限制-shim-自己" tabindex="-1">5.6 setSpeedLimit 不限制 Shim 自己 <a class="header-anchor" href="#_5-6-setspeedlimit-不限制-shim-自己" aria-label="Permalink to &quot;5.6 setSpeedLimit 不限制 Shim 自己&quot;">​</a></h3><p><code>setSpeedLimit()</code> 只把速度限制转发给 <code>primary_controller_</code>。它不会缩放 <code>rotate_to_heading_angular_vel</code> 或 <code>max_angular_accel</code>。</p><p>因此 Controller Server 对该插件施加 SpeedLimit 时，内部 DWB 会响应，而前置原地旋转仍使用 Shim 自己的固定参数。</p><h2 id="六、每条旋转命令先推演-footprint" tabindex="-1">六、每条旋转命令先推演 Footprint <a class="header-anchor" href="#六、每条旋转命令先推演-footprint" aria-label="Permalink to &quot;六、每条旋转命令先推演 Footprint&quot;">​</a></h2><p><img src="`+p+`" alt="原地旋转碰撞预测与实现边界"></p><h3 id="_6-1-推演模型只有-yaw-变化" tabindex="-1">6.1 推演模型只有 yaw 变化 <a class="header-anchor" href="#_6-1-推演模型只有-yaw-变化" aria-label="Permalink to &quot;6.1 推演模型只有 yaw 变化&quot;">​</a></h3><p>旋转命令生成后，<code>isCollisionFree()</code> 保持机器人 <code>x</code>、<code>y</code> 不变，只推进：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>yaw(t) = initial_yaw + w_cmd * t</span></span></code></pre></div><p>时间按 <code>control_duration</code> 离散递增，最多检查到 <code>simulate_ahead_time</code>。当前是每 <code>0.05 s</code> 检查一次，最远预测 <code>1.0 s</code>。</p><h3 id="_6-2-每个预测姿态检查完整-footprint" tabindex="-1">6.2 每个预测姿态检查完整 Footprint <a class="header-anchor" href="#_6-2-每个预测姿态检查完整-footprint" aria-label="Permalink to &quot;6.2 每个预测姿态检查完整 Footprint&quot;">​</a></h3><p>每个模拟 yaw 都调用 <code>FootprintCollisionChecker::footprintCostAtPose()</code>。虽然机器人中心没有平移，长方形或不对称 Footprint 在旋转时会扫过新的 Costmap 栅格，因此原地旋转仍可能碰撞。</p><p>返回代价达到 <code>LETHAL_OBSTACLE</code> 时，函数抛出碰撞异常。</p><h3 id="_6-3-未知空间在跟踪未知区域时也被拒绝" tabindex="-1">6.3 未知空间在跟踪未知区域时也被拒绝 <a class="header-anchor" href="#_6-3-未知空间在跟踪未知区域时也被拒绝" aria-label="Permalink to &quot;6.3 未知空间在跟踪未知区域时也被拒绝&quot;">​</a></h3><p>如果 Footprint 代价为 <code>NO_INFORMATION</code>，并且 Layered Costmap 正在跟踪未知空间，源码同样把它视为潜在碰撞并抛出异常。</p><p>这是一种保守策略：未知区域不是“没有障碍证据”，而是“缺少安全证据”。</p><h3 id="_6-4-推演试图在交还控制权前停止" tabindex="-1">6.4 推演试图在交还控制权前停止 <a class="header-anchor" href="#_6-4-推演试图在交还控制权前停止" aria-label="Permalink to &quot;6.4 推演试图在交还控制权前停止&quot;">​</a></h3><p>源码先计算：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>remaining =</span></span>
<span class="line"><span>  abs(e_theta) - angular_dist_threshold</span></span></code></pre></div><p>然后试图在预计旋转量达到 <code>remaining</code> 时停止模拟，避免继续检查本应由主控制器接管的姿态。</p><p>但这里始终使用进入阈值 <code>angular_dist_threshold</code>，没有在 <code>in_rotation_</code> 状态下切换为更小的 <code>angular_disengage_threshold</code>。实际控制会旋转到退出阈值附近，而碰撞推演可能更早停止。</p><h3 id="_6-5-正负方向的提前停止判断不对称" tabindex="-1">6.5 正负方向的提前停止判断不对称 <a class="header-anchor" href="#_6-5-正负方向的提前停止判断不对称" aria-label="Permalink to &quot;6.5 正负方向的提前停止判断不对称&quot;">​</a></h3><p>当前停止条件是：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>shortest_angular_distance(</span></span>
<span class="line"><span>  simulated_yaw,</span></span>
<span class="line"><span>  initial_yaw</span></span>
<span class="line"><span>) &gt;= remaining</span></span></code></pre></div><p><code>remaining</code> 是非负标量，但顺时针旋转得到的 shortest angular distance 为负值。于是逆时针分支可能提前停止，顺时针分支通常不会命中这个条件，会继续推演到完整 <code>simulate_ahead_time</code>。</p><p>当误差已经小于进入阈值时，<code>remaining</code> 还是负数，逆时针分支甚至可能在初次 Footprint 检查前就退出循环。</p><p>这是当前本地源码的实现边界，不是期望中的方向对称安全模型。若把 Shim 用于紧邻障碍的起步旋转，应针对正负角误差分别做场景验证。</p><h2 id="七、末端航向旋转是一个可选高优先级分支" tabindex="-1">七、末端航向旋转是一个可选高优先级分支 <a class="header-anchor" href="#七、末端航向旋转是一个可选高优先级分支" aria-label="Permalink to &quot;七、末端航向旋转是一个可选高优先级分支&quot;">​</a></h2><h3 id="_7-1-当前配置默认关闭" tabindex="-1">7.1 当前配置默认关闭 <a class="header-anchor" href="#_7-1-当前配置默认关闭" aria-label="Permalink to &quot;7.1 当前配置默认关闭&quot;">​</a></h3><p><code>rotate_to_goal_heading=false</code>，所以现用配置只做新路径初始旋转，目标末端航向继续由内部 DWB 和外部 GoalChecker 处理。</p><p>启用后，这个分支位于 <code>computeVelocityCommands()</code> 的最前面，优先级高于新路径初始旋转和主控制器委托。</p><h3 id="_7-2-先判断目标位置是否到达" tabindex="-1">7.2 先判断目标位置是否到达 <a class="header-anchor" href="#_7-2-先判断目标位置是否到达" aria-label="Permalink to &quot;7.2 先判断目标位置是否到达&quot;">​</a></h3><p>Shim 读取 Path 最后一个 Pose，把它变换到当前机器人 Pose 的 frame，再从外部 GoalChecker 获取 XY 容差，并写入内部 <code>PositionGoalChecker</code>。</p><p>只有机器人位置进入 XY 容差时，才计算：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>e_goal =</span></span>
<span class="line"><span>  shortest_angular_distance(robot_yaw, goal_yaw)</span></span></code></pre></div><p>随后复用同一套角速度生成和碰撞预测。</p><h3 id="_7-3-它没有独立的目标航向完成阈值" tabindex="-1">7.3 它没有独立的目标航向完成阈值 <a class="header-anchor" href="#_7-3-它没有独立的目标航向完成阈值" aria-label="Permalink to &quot;7.3 它没有独立的目标航向完成阈值&quot;">​</a></h3><p>位置满足后，源码不再检查一个 Shim 自己的 yaw tolerance。只要内部 <code>PositionGoalChecker</code> 仍判断位置到达，每周期都会调用旋转命令生成。</p><p>当 <code>e_goal=0</code> 时，符号表达式仍选择负方向，并给出负目标角速度，经加速度窗口限制后可能不是零。</p><p>因此在这份 <code>1.1.20</code> 实现中，开启 <code>rotate_to_goal_heading</code> 需要特别验证零误差和最终停止行为。当前配置保持关闭，避开了这一边界。</p><h2 id="八、异常回退不是统一的安全停止" tabindex="-1">八、异常回退不是统一的安全停止 <a class="header-anchor" href="#八、异常回退不是统一的安全停止" aria-label="Permalink to &quot;八、异常回退不是统一的安全停止&quot;">​</a></h2><h3 id="_8-1-初始旋转异常会委托主控制器" tabindex="-1">8.1 初始旋转异常会委托主控制器 <a class="header-anchor" href="#_8-1-初始旋转异常会委托主控制器" aria-label="Permalink to &quot;8.1 初始旋转异常会委托主控制器&quot;">​</a></h3><p>新路径采样、TF 或碰撞检查失败时，起步分支记录调试日志、清除 <code>path_updated_</code>，随后调用 DWB。</p><p>这让系统不会因为 Shim 自己无法工作而永久阻塞，但也意味着“Shim 检测到旋转碰撞”不等于“本周期一定输出零速度”。最终行为取决于 DWB 是否能生成安全命令。</p><h3 id="_8-2-末端旋转异常也会继续向下" tabindex="-1">8.2 末端旋转异常也会继续向下 <a class="header-anchor" href="#_8-2-末端旋转异常也会继续向下" aria-label="Permalink to &quot;8.2 末端旋转异常也会继续向下&quot;">​</a></h3><p>目标末端分支捕获异常后没有立即停止，而是继续检查新路径旋转，最后仍可能委托主控制器。</p><p>Rotation Shim 的安全语义是拒绝当前这条原地旋转候选，不是为整个 Controller Server 实现急停。</p><h3 id="_8-3-主控制器异常仍会向上传播" tabindex="-1">8.3 主控制器异常仍会向上传播 <a class="header-anchor" href="#_8-3-主控制器异常仍会向上传播" aria-label="Permalink to &quot;8.3 主控制器异常仍会向上传播&quot;">​</a></h3><p>委托 DWB 后，源码不再捕获其 <code>computeVelocityCommands()</code> 异常。DWB 找不到合法轨迹、Path 无效或 TF 失败时，错误会继续交给 Controller Server 的失败处理链。</p><h3 id="_8-4-碰撞检测锁住当前-costmap" tabindex="-1">8.4 碰撞检测锁住当前 Costmap <a class="header-anchor" href="#_8-4-碰撞检测锁住当前-costmap" aria-label="Permalink to &quot;8.4 碰撞检测锁住当前 Costmap&quot;">​</a></h3><p>新路径起步分支先取得 Costmap mutex，再锁住 Shim 自身 mutex，采样、TF、命令生成和 Footprint 推演都在锁内完成。</p><p>它保证本次预测看到一致的 Costmap，但 TF 等待或多步 Footprint 查询也会延长 Costmap 被占用的时间。</p><h2 id="九、现用参数如何共同塑造行为" tabindex="-1">九、现用参数如何共同塑造行为 <a class="header-anchor" href="#九、现用参数如何共同塑造行为" aria-label="Permalink to &quot;九、现用参数如何共同塑造行为&quot;">​</a></h2><h3 id="_9-1-当前核心参数快照" tabindex="-1">9.1 当前核心参数快照 <a class="header-anchor" href="#_9-1-当前核心参数快照" aria-label="Permalink to &quot;9.1 当前核心参数快照&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>primary_controller           = dwb_core::DWBLocalPlanner</span></span>
<span class="line"><span>angular_dist_threshold       = 0.785 rad</span></span>
<span class="line"><span>angular_disengage_threshold  = 0.3925 rad</span></span>
<span class="line"><span>forward_sampling_distance    = 0.5 m</span></span>
<span class="line"><span>rotate_to_heading_angular_vel= 0.8 rad/s</span></span>
<span class="line"><span>max_angular_accel            = 3.2 rad/s²</span></span>
<span class="line"><span>simulate_ahead_time          = 1.0 s</span></span>
<span class="line"><span>rotate_to_goal_heading       = false</span></span>
<span class="line"><span>closed_loop                  = true</span></span>
<span class="line"><span>controller_frequency         = 20 Hz</span></span></code></pre></div><p>这组参数表达的是：路径粗略方向偏差超过四十五度才接管，旋转到二十二点五度以内再退出；用半米尺度观察路径方向，以最高 <code>0.8 rad/s</code> 原地旋转，每周期最多改变 <code>0.16 rad/s</code>，并向前检查一秒 Footprint。</p><h3 id="_9-2-forward-sampling-distance-决定看的是局部噪声还是整体趋势" tabindex="-1">9.2 forward_sampling_distance 决定看的是局部噪声还是整体趋势 <a class="header-anchor" href="#_9-2-forward-sampling-distance-决定看的是局部噪声还是整体趋势" aria-label="Permalink to &quot;9.2 forward_sampling_distance 决定看的是局部噪声还是整体趋势&quot;">​</a></h3><p>取值太小，采样点容易受路径首端离散噪声影响，Shim 可能对一个很短的小折线做激烈旋转。</p><p>取值太大，起始急弯会被平均成更远的净方向，机器人对最初可行走廊反应不足；短 Path 还可能根本找不到采样点，直接回退 DWB。</p><h3 id="_9-3-两个角阈值必须保留合理间隔" tabindex="-1">9.3 两个角阈值必须保留合理间隔 <a class="header-anchor" href="#_9-3-两个角阈值必须保留合理间隔" aria-label="Permalink to &quot;9.3 两个角阈值必须保留合理间隔&quot;">​</a></h3><p><code>angular_disengage_threshold</code> 应小于 <code>angular_dist_threshold</code>，才能形成真正的迟滞。</p><p>两者太接近，噪声更容易造成边界抖动；退出阈值太小，则原地旋转时间更长，而且当前碰撞推演却仍按进入阈值估算停止点，安全检查和真实接管区间的偏差会扩大。</p><h3 id="_9-4-角速度与加速度不能脱离底盘能力" tabindex="-1">9.4 角速度与加速度不能脱离底盘能力 <a class="header-anchor" href="#_9-4-角速度与加速度不能脱离底盘能力" aria-label="Permalink to &quot;9.4 角速度与加速度不能脱离底盘能力&quot;">​</a></h3><p><code>rotate_to_heading_angular_vel</code> 决定稳定旋转幅值，<code>max_angular_accel</code> 决定爬升和换向速度。</p><p>提高目标角速度却不增加安全前视时间，会让相同一秒内扫过更大的角度；提高加速度又缺少剩余角度制动约束，会增加越过退出窗口的风险。</p><h3 id="_9-5-closed-loop-依赖可靠-odom" tabindex="-1">9.5 closed_loop 依赖可靠 Odom <a class="header-anchor" href="#_9-5-closed-loop-依赖可靠-odom" aria-label="Permalink to &quot;9.5 closed_loop 依赖可靠 Odom&quot;">​</a></h3><p>闭环模式能基于真实响应限制下一周期命令，是更符合物理系统的选择。但 Odom 延迟、角速度符号错误或长期为零，会让加速度窗口围绕错误状态展开。</p><p>开环不依赖反馈，却默认底盘忠实执行上一条命令。两种模式不是“一个先进、一个落后”，而是使用不同的状态来源。</p><h2 id="十、一次控制周期的数据流" tabindex="-1">十、一次控制周期的数据流 <a class="header-anchor" href="#十、一次控制周期的数据流" aria-label="Permalink to &quot;十、一次控制周期的数据流&quot;">​</a></h2><h3 id="_10-1-目标位置分支先获得检查机会" tabindex="-1">10.1 目标位置分支先获得检查机会 <a class="header-anchor" href="#_10-1-目标位置分支先获得检查机会" aria-label="Permalink to &quot;10.1 目标位置分支先获得检查机会&quot;">​</a></h3><p>启用末端航向旋转时，先读取 Path 末点、完成 TF、同步 XY 容差并判断位置是否到达。命中后生成旋转命令和碰撞预测，安全则立即返回。</p><h3 id="_10-2-新路径分支计算粗略航向" tabindex="-1">10.2 新路径分支计算粗略航向 <a class="header-anchor" href="#_10-2-新路径分支计算粗略航向" aria-label="Permalink to &quot;10.2 新路径分支计算粗略航向&quot;">​</a></h3><p><code>path_updated_</code> 为真时，从 Path 首点向前寻找半米采样点，变换到 base frame，计算 <code>atan2(y,x)</code>，再根据 <code>in_rotation_</code> 选择进入或退出阈值。</p><h3 id="_10-3-需要接管时只输出角速度" tabindex="-1">10.3 需要接管时只输出角速度 <a class="header-anchor" href="#_10-3-需要接管时只输出角速度" aria-label="Permalink to &quot;10.3 需要接管时只输出角速度&quot;">​</a></h3><p>误差超过当前阈值时，目标角速度先经过闭环或开环加速度窗口，再推演 Footprint。安全时返回 <code>linear.x=0</code>、<code>angular.z=w_cmd</code>。</p><h3 id="_10-4-不需要接管时永久交还本条-path" tabindex="-1">10.4 不需要接管时永久交还本条 Path <a class="header-anchor" href="#_10-4-不需要接管时永久交还本条-path" aria-label="Permalink to &quot;10.4 不需要接管时永久交还本条 Path&quot;">​</a></h3><p>误差进入退出窗口后，<code>path_updated_</code> 被清除。当前周期随即调用 DWB；后续周期继续直达 DWB，直到下一次 <code>setPlan()</code>。</p><h3 id="_10-5-last-angular-vel-连接两种输出来源" tabindex="-1">10.5 last_angular_vel_ 连接两种输出来源 <a class="header-anchor" href="#_10-5-last-angular-vel-连接两种输出来源" aria-label="Permalink to &quot;10.5 last_angular_vel_ 连接两种输出来源&quot;">​</a></h3><p>无论输出来自 Shim 还是 DWB，源码都会保存其 <code>angular.z</code> 到 <code>last_angular_vel_</code>。</p><p>开环模式下，下一次 Shim 接管可以从上一条实际下发命令附近继续限加速度，而不是总从零开始。代价是 DWB 的末次角速度也会成为 Shim 的开环初值。</p><h2 id="十一、真正值得记住的算法结论" tabindex="-1">十一、真正值得记住的算法结论 <a class="header-anchor" href="#十一、真正值得记住的算法结论" aria-label="Permalink to &quot;十一、真正值得记住的算法结论&quot;">​</a></h2><h3 id="_11-1-shim-解决的是控制器接入条件" tabindex="-1">11.1 Shim 解决的是控制器接入条件 <a class="header-anchor" href="#_11-1-shim-解决的是控制器接入条件" aria-label="Permalink to &quot;11.1 Shim 解决的是控制器接入条件&quot;">​</a></h3><p>它不优化 Path，也不替代 DWB。它把“大航向误差下直接平移跟踪”变成“先原地把方向拉回可处理区间，再正常跟踪”。</p><h3 id="_11-2-半米采样加双阈值构成核心" tabindex="-1">11.2 半米采样加双阈值构成核心 <a class="header-anchor" href="#_11-2-半米采样加双阈值构成核心" aria-label="Permalink to &quot;11.2 半米采样加双阈值构成核心&quot;">​</a></h3><p>前方采样点提供稳定的粗略路径方向，进入／退出双阈值提供状态迟滞。这两部分共同决定是否接管和何时交还控制权。</p><h3 id="_11-3-角速度控制只有加速度窗口" tabindex="-1">11.3 角速度控制只有加速度窗口 <a class="header-anchor" href="#_11-3-角速度控制只有加速度窗口" aria-label="Permalink to &quot;11.3 角速度控制只有加速度窗口&quot;">​</a></h3><p>当前实现没有按剩余角度建立制动上界。控制是否平顺不仅取决于 Shim 参数，也取决于底盘响应、Odom、Velocity Smoother 和 DWB 接手后的命令。</p><h3 id="_11-4-碰撞推演必须按源码边界理解" tabindex="-1">11.4 碰撞推演必须按源码边界理解 <a class="header-anchor" href="#_11-4-碰撞推演必须按源码边界理解" aria-label="Permalink to &quot;11.4 碰撞推演必须按源码边界理解&quot;">​</a></h3><p>它确实检查旋转 Footprint，但提前停止使用进入阈值，且正负旋转的符号判断不对称。紧邻障碍应用不能只看到 <code>simulate_ahead_time=1.0</code> 就认为两侧都得到等价的一秒安全覆盖。</p><h3 id="_11-5-当前配置关闭末端旋转是重要事实" tabindex="-1">11.5 当前配置关闭末端旋转是重要事实 <a class="header-anchor" href="#_11-5-当前配置关闭末端旋转是重要事实" aria-label="Permalink to &quot;11.5 当前配置关闭末端旋转是重要事实&quot;">​</a></h3><p>现用 Rotation Shim 只做起步方向扶正。末端航向由 DWB 与 GoalChecker 处理，也避开了本版本末端分支在零角误差时仍可能生成负向命令的边界。</p><p>Rotation Shim 的价值，不是让控制器更聪明，而是让主控制器在更合适的初始条件下开始工作。机器人先把方向扶正，再把复杂问题交给真正擅长路径跟踪的算法，这正是它简单却实用的原因。</p>`,185)])])}const x=e(c,[["render",h]]);export{P as __pageData,x as default};
